   370→
   371→	return lp;
   372→}
   373→void FreeTimeout( stTimeout_t *apTimeout )
   374→{
   375→	free( apTimeout->pItems );
   376→	free ( apTimeout );
   377→}
   378→int AddTimeout( stTimeout_t *apTimeout,stTimeoutItem_t *apItem ,unsigned long long allNow )
   379→{
   380→	if( apTimeout->ullStart == 0 )
   381→	{
   382→		apTimeout->ullStart = allNow;
   383→		apTimeout->llStartIdx = 0;
   384→	}
   385→	if( allNow < apTimeout->ullStart )
   386→	{
   387→		co_log_err("CO_ERR: AddTimeout line %d allNow %llu apTimeout->ullStart %llu",
   388→					__LINE__,allNow,apTimeout->ullStart);
   389→
   390→		return __LINE__;
   391→	}
   392→	if( apItem->ullExpireTime < allNow )
   393→	{
   394→		co_log_err("CO_ERR: AddTimeout line %d apItem->ullExpireTime %llu allNow %llu apTimeout->ullStart %llu",
   395→					__LINE__,apItem->ullExpireTime,allNow,apTimeout->ullStart);
   396→
   397→		return __LINE__;
   398→	}
   399→	unsigned long long diff = apItem->ullExpireTime - apTimeout->ullStart;
   400→
   401→	if( diff >= (unsigned long long)apTimeout->iItemSize )
   402→	{
   403→		diff = apTimeout->iItemSize - 1;
   404→		co_log_err("CO_ERR: AddTimeout line %d diff %d",
   405→					__LINE__,diff);
   406→
   407→		//return __LINE__;
   408→	}
   409→	AddTail( apTimeout->pItems + ( apTimeout->llStartIdx + diff ) % apTimeout->iItemSize , apItem );
   410→
   411→	return 0;
   412→}
   413→inline void TakeAllTimeout( stTimeout_t *apTimeout,unsigned long long allNow,stTimeoutItemLink_t *apResult )
   414→{
   415→	if( apTimeout->ullStart == 0 )
   416→	{
   417→		apTimeout->ullStart = allNow;
   418→		apTimeout->llStartIdx = 0;
   419→	}
   420→
   421→	if( allNow < apTimeout->ullStart )
   422→	{
   423→		return ;
   424→	}
   425→	int cnt = allNow - apTimeout->ullStart + 1;
   426→	if( cnt > apTimeout->iItemSize )
   427→	{
   428→		cnt = apTimeout->iItemSize;
   429→	}
   430→	if( cnt < 0 )
   431→	{
   432→		return;
   433→	}
   434→	for( int i = 0;i<cnt;i++)
   435→	{
   436→		int idx = ( apTimeout->llStartIdx + i) % apTimeout->iItemSize;
   437→		Join<stTimeoutItem_t,stTimeoutItemLink_t>( apResult,apTimeout->pItems + idx  );
   438→	}
   439→	apTimeout->ullStart = allNow;
   440→	apTimeout->llStartIdx += cnt - 1;
   441→
   442→
   443→}
   444→static int CoRoutineFunc( stCoRoutine_t *co,void * )
   445→{
