   717→static uint32_t PollEvent2Epoll( short events )
   718→{
   719→	uint32_t e = 0;	
   720→	if( events & POLLIN ) 	e |= EPOLLIN;
   721→	if( events & POLLOUT )  e |= EPOLLOUT;
   722→	if( events & POLLHUP ) 	e |= EPOLLHUP;
   723→	if( events & POLLERR )	e |= EPOLLERR;
   724→	if( events & POLLRDNORM ) e |= EPOLLRDNORM;
   725→	if( events & POLLWRNORM ) e |= EPOLLWRNORM;
   726→	return e;
   727→}
   728→static short EpollEvent2Poll( uint32_t events )
   729→{
   730→	short e = 0;	
   731→	if( events & EPOLLIN ) 	e |= POLLIN;
   732→	if( events & EPOLLOUT ) e |= POLLOUT;
   733→	if( events & EPOLLHUP ) e |= POLLHUP;
   734→	if( events & EPOLLERR ) e |= POLLERR;
   735→	if( events & EPOLLRDNORM ) e |= POLLRDNORM;
   736→	if( events & EPOLLWRNORM ) e |= POLLWRNORM;
   737→	return e;
   738→}
